import { Injectable } from '@angular/core';
import { Router, UrlTree } from '@angular/router';

export const MULTI_DEVICE_EXEMPT_CASE_ID = '966922a8-1e20-4ea5-8b79-10a395b7fea9';
export const MULTI_DEVICE_SESSION_KEY = 'multi_device_case_active';

export function isMultiDeviceExempt(): boolean {
  return localStorage.getItem(MULTI_DEVICE_SESSION_KEY) === 'true';
}
import { Team } from '../../userpanel/interfaces/userdashboard.interface';
import { DialogueComponent } from '../../shared/components/dialogue/dialogue.component';
import { MatDialog } from '@angular/material/dialog';
import moment from 'moment';
import { bundleDetailRes } from '../../shared/interfaces/myfile.interface';
import { DomSanitizer } from '@angular/platform-browser';
import { highlightModeType } from '../../pdf/interfaces/pdf.interface';
import { Clipboard } from '@angular/cdk/clipboard';
import { BroadcastingService } from '../services/broadcasting/broadcasting.service';
import { take } from 'rxjs';
import { broadCastBody } from '../interfaces/login.interface';
import { BROADCAST_EVENTS } from '../../userpanel/utility/user-panel-constants';
import { advanceFiler } from '../../userpanel/interfaces/advance-search.interface';
import { TostbarService } from '../services/tost/tostbar.service';
import {
  COLOR_MAP,
  createDefaultSearchFilter,
  type ColorMap,
  type SearchFilterGroup,
} from '../../shared/interfaces/commonfunction.interface';

interface Initials {
  Fn: string;
  Ln: string;
  bg: string;
}
@Injectable({
  providedIn: 'root'
})
export class CommonfunctionService {
  private static readonly VALID_PROTOCOLS = new Set(['http:', 'https:']);

  private static buildIndividualDocUrl(payload: unknown): string {
    return `${globalThis.location.origin}/individual/doc/${encodeURIComponent(JSON.stringify(payload))}`;
  }

  readonly colorMap: ColorMap = COLOR_MAP;
  searchFilter: SearchFilterGroup[] = createDefaultSearchFilter();
  searchText: string = '';
  searchName: any = 'C'; searchdate: any = 'A'; searchin: any = 'M'


  isPagination: boolean = false;
  paginationdata: any;
  paginationIDs: string[] = [];
  displaytype: string = '';
  jFTypes: string[] = [];

  isConvert: boolean = false;
  convertData: { queueLength: number, total_prog: number } = { queueLength: 0, total_prog: 0 };

  viewlist: bundleDetailRes[] = [];

  openedWindow: Window | null = null;
  constructor(public router: Router, public dialog: MatDialog, private readonly sanitizer: DomSanitizer, private readonly clipboard: Clipboard,
    readonly broadCastService: BroadcastingService, public tost: TostbarService,
  ) { }

  resetState(): void {
    this.searchFilter = createDefaultSearchFilter();
    this.searchText = '';
    this.searchName = 'C';
    this.searchdate = 'A';
    this.searchin = 'M';
    this.isPagination = false;
    this.paginationdata = undefined;
    this.paginationIDs = [];
    this.displaytype = '';
    this.jFTypes = [];
    this.viewlist = [];
  }

  private getUserInitials(x: any): Initials | null {
    if (!x) {
      return null;
    }

    const firstNameInitial = x?.cFname ? x.cFname.substring(0, 1).toUpperCase() : '';
    const lastNameInitial = x?.cLname ? x.cLname.substring(0, 1).toUpperCase() : '';
    const background = firstNameInitial ? this.initialcolor(firstNameInitial) : this.initialcolor('');

    return { Fn: firstNameInitial.toString(), Ln: lastNameInitial, bg: background };
  }

  async get_userinit(x: any): Promise<Initials | null> {
    return this.getUserInitials(x);
  }

  get_userinit2(x: any): Initials | null {
    return this.getUserInitials(x);
  }

  initialcolor(initial: string): string {
    for (const [color, letters] of Object.entries(this.colorMap)) {
      if (letters.includes(initial.toUpperCase())) {
        return color;
      }
    }
    return 'bg-orange-600';
  }

  goto(path, mdl?) {
    if (mdl && Object.keys(mdl).length) {
      const url = btoa(JSON.stringify(mdl));
      this.router.navigate([path, url], { relativeTo: null });
    } else {
      this.router.navigate([path], { replaceUrl: true });
    }
  }


  gotoEncoduri(path, mdl?) {
    if (mdl && Object.keys(mdl).length) {
      const url = encodeURIComponent(JSON.stringify(mdl));
      this.router.navigate([path, url], { relativeTo: null });
    } else {
      this.router.navigate([path]);
    }
  }


  async fetchRoleid(teams: Team[], nUserid: string): Promise<number> {
    let nMyroleid = 0;
    try {
      if (nUserid && teams?.length) {
        for (const x of teams) {
          if (x.users?.length) {
            const userObj: any = x.users.find(a => a.nUserid == nUserid);
            if (userObj) {
              nMyroleid = userObj.nRoleid;
              break;
            }
          }
        }
      }
    } catch (error) {
      console.error('Failed to fetchRoleid', nUserid, error);
      nMyroleid = 0;
    }

    return nMyroleid;
  }



  opendialog(type, head, desc, button1, button2?, checkbox?) {
    const dialogRef = this.dialog.open(DialogueComponent, {
      width: 'fit-content',
      minWidth: '500px',
      height: 'fit-content',
      data: {
        'type': type, // 'I'
        'heading': head,
        'desc': desc,
        'button1': button1 ?? '',
        'button2': button2 ?? '',
        'checkbox': checkbox ?? '',
      }
    });
    dialogRef.afterClosed().subscribe(() => {})
  }

  getCurrentTime(): string {
    return moment().format();  // Moment uses the system's local timezone by default
  }

  getDateFormate(dt: any, formate: string): string {
    return moment(dt).format(formate);  // Moment uses the system's local timezone by default
  }

  // senitizeUrl(path: string, nBundledetailid: string, nCaseid: string, isFullmode?: boolean, isLink?: highlightModeType, pageNo?: number, isRealtime?: boolean,
  //   compareMode?: boolean, compareIndex?: number, linkExplorerMode?: string, linkExplorerType?: string, nRFSid?: string, nRDocid?: string, nRWebid?: string, isMyfile?: boolean, activesectiontype?: string, nSectionid?: string, nPresentid?: string, isHost?: boolean, jFilter?: string) {
  //   return this.sanitizer.bypassSecurityTrustResourceUrl(`viewer/pdf/${btoa(path)}?nBundledetailid=${nBundledetailid}&nCaseid=${nCaseid}&fullmode=${isFullmode ? 'Y' : 'N'}&isLink=${isLink ? isLink : 'N'}&page=${pageNo ? pageNo : 1}&isRealtime=${isRealtime ? 'Y' : 'N'}&compareMode=${compareMode ? 'Y' : 'N'}&compareIndex=${compareIndex ? compareIndex : 0}&linkExplorerMode=${linkExplorerMode ? linkExplorerMode : ''}&linkExplorerType=${linkExplorerType ? linkExplorerType : ''}&nRFSid=${nRFSid || null}&nRDocid=${nRDocid || null}&nRWebid=${nRWebid || null}&isMyfile=${isMyfile || false}&activesectiontype=${activesectiontype || 'MB'}&nSectionid=${nSectionid}&nPresentid=${nPresentid}&isHost=${isHost ? 'Y' : 'N'}&jFilter=${jFilter}`);
  // }

  private static createPdfViewerUrl(path: string, params: URLSearchParams): string {
    return `viewer/pdf/${btoa(path)}?${params.toString()}`;
  }

  private static yes(): string {
    return 'Y';
  }

  private static no(): string {
    return 'N';
  }

  senitizeUrl(...args: [
    path: string,
    nBundledetailid: string,
    nCaseid: string,
    isFullmode?: boolean,
    isLink?: highlightModeType,
    pageNo?: number,
    isRealtime?: boolean,
    compareMode?: boolean,
    compareIndex?: number,
    linkExplorerMode?: string,
    linkExplorerType?: string,
    nRFSid?: string,
    nRDocid?: string,
    nRWebid?: string,
    isMyfile?: boolean,
    activesectiontype?: string,
    nSectionid?: string,
    nPresentid?: string,
    isHost?: boolean,
    jFilter?: string,
    lineNo?: number,
    isPresenter?: boolean
  ]) {
    const [
      path,
      nBundledetailid,
      nCaseid,
      isFullmode,
      isLink,
      pageNo,
      isRealtime,
      compareMode,
      compareIndex,
      linkExplorerMode,
      linkExplorerType,
      nRFSid,
      nRDocid,
      nRWebid,
      isMyfile,
      activesectiontype,
      nSectionid,
      nPresentid,
      isHost,
      jFilter,
      lineNo,
      isPresenter,
    ] = args;

    const params = new URLSearchParams();
    params.set('nBundledetailid', nBundledetailid);
    params.set('nCaseid', nCaseid);
    params.set('fullmode', isFullmode ? CommonfunctionService.yes() : CommonfunctionService.no());
    params.set('isLink', (isLink ?? 'N') as string);
    params.set('page', String(pageNo ?? 1));
    params.set('isRealtime', isRealtime ? CommonfunctionService.yes() : CommonfunctionService.no());
    params.set('compareMode', compareMode ? CommonfunctionService.yes() : CommonfunctionService.no());
    params.set('compareIndex', String(compareIndex ?? 0));
    params.set('linkExplorerMode', linkExplorerMode ?? '');
    params.set('linkExplorerType', linkExplorerType ?? '');
    if (nRFSid) params.set('nRFSid', nRFSid);
    if (nRDocid) params.set('nRDocid', nRDocid);
    if (nRWebid) params.set('nRWebid', nRWebid);
    params.set('isMyfile', String(isMyfile ?? false));
    params.set('activesectiontype', activesectiontype ?? 'MB');
    if (nSectionid) params.set('nSectionid', nSectionid);
    if (nPresentid) params.set('nPresentid', nPresentid);
    params.set('isHost', isHost ? CommonfunctionService.yes() : CommonfunctionService.no());
    params.set('jFilter', jFilter ?? '');
    params.set('lineNo', String(lineNo ?? 1));
    params.set('isPresenter', isPresenter ? CommonfunctionService.yes() : CommonfunctionService.no());

    return this.sanitizer.bypassSecurityTrustResourceUrl(CommonfunctionService.createPdfViewerUrl(path, params));
  }


  senitizeQuick(nBundledetailid: string, nPage: number, nCaseid) {
    return this.sanitizer.bypassSecurityTrustResourceUrl(`quickview/${nBundledetailid}?nPage=${nPage}&nCaseid=${nCaseid}`);
  }

  notfoundUrl() {
    return this.sanitizer.bypassSecurityTrustResourceUrl(`empty?icon=pdf`)
  }
  copyText(text: string): void {
    this.clipboard.copy(text);
  }
  validateUrl(url: string): boolean {
    const trimmed = url?.trim();
    if (!trimmed) {
      return false;
    }

    try {
      const candidate = /^(https?:)?\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
      const parsed = new URL(candidate);
      return CommonfunctionService.VALID_PROTOCOLS.has(parsed.protocol);
    } catch {
      return false;
    }
  }

  gotoUrl(path: string, mdl?: any) {

    if (mdl && Object.keys(mdl).length) {
      const data = encodeURIComponent(JSON.stringify(mdl));
      this.router.navigate([path, data], { relativeTo: null });
    } else {
      this.router.navigate([path]);
    }
  }


  openTab(nBundledetailid: string, nCaseid: string, nPresentid: string, cIsindex: boolean): Promise<boolean> {
    return new Promise((resolve, reject) => {
      const timeot = setTimeout(() => {
        reject(new Error('No tab open'));
      }, 200);
      this.broadCastService.indiOpenExistsListener().pipe(take(1)).subscribe((body: broadCastBody) => {
        clearTimeout(timeot);
        resolve(true)
      });
      this.broadCastService.portMessage({ event: BROADCAST_EVENTS.INDIVIDUAL_OPEN_TAB, data: { nCaseid: nCaseid, nBundledetailid: nBundledetailid, nPresentid: nPresentid, cIsindex: cIsindex } });
    })

  }


  async openHyperLinkFile(...args: [
    nBundledetailid: any,
    nCaseid: any,
    nPresentid?: string,
    jFilter?: advanceFiler,
    cIsindex?: boolean,
    nPageno?: number,
    nFSid?: string | null,
    nRFSid?: string | null,
    nDocid?: string | null,
    nWebid?: string | null,
    activesectiontype?: string
  ]) {
    const [nBundledetailid, nCaseid, nPresentid, jFilter, cIsindex, nPageno, nFSid, nRFSid, nDocid, nWebid, activesectiontype] = args;

    const url = CommonfunctionService.buildIndividualDocUrl([[[nBundledetailid, nPageno || 1, nFSid, nRFSid, nDocid, nWebid, jFilter]], nCaseid, nPresentid, null]);

    if (cIsindex) {
      const indexWindow = globalThis.open(url, `doc_${nCaseid}_index`);
      indexWindow?.focus();
      return;
    }

    try {
      await this.openTab(nBundledetailid, nCaseid, nPresentid, cIsindex);
      this.broadCastService.portMessage({ event: BROADCAST_EVENTS.INDIVIDUAL_MULTIPLE_TAB, data: { nCaseid: nCaseid, bId: nBundledetailid, nPresentid, cIsindex, nPageno, nFSid, nRFSid, nDocid, nWebid, activesectiontype } });
      this.openedWindow = globalThis.open('', `doc_${nCaseid}`);
      this.openedWindow?.focus();
    } catch {
      this.openedWindow = globalThis.open(url, `doc_${nCaseid}`);
      this.openedWindow?.focus();
    }
  }

  async navigateToindividual(nBundledetailid, nPageno, nCaseid, nPresentid?: string) {
    this.router.navigateByUrl(
      `/individual/doc/${encodeURIComponent(
        JSON.stringify([[[nBundledetailid, nPageno]], nCaseid, nPresentid])
      )}`
    );
  }

  OpenInNewTab(path: string, mdl?: any) {
    let urlSegments: any[] = [path];

    if (mdl && Object.keys(mdl).length > 0) {
      const encoded = btoa(JSON.stringify(mdl));
      urlSegments.push(encoded);
    }

    const tree: UrlTree = this.router.createUrlTree(urlSegments);
    const fullUrl: string = this.router.serializeUrl(tree);

    // Open in new tab
    const baseUrl = globalThis.location.origin;
    globalThis.open(baseUrl + fullUrl, '_blank');
  }

  /**
   * Opens a transcript / RT session as a new tab in an existing individual-doc
   * window (keyed by nCaseid), or in a fresh window if none is open. Mirrors
   * openHyperLinkFile's broadcast-then-fallback pattern, but carries nSesid in
   * the payload so the receiver can build a session DocumentTab instead of a
   * PDF DocumentTab.
   */
  async openSessionInIndividualDoc(nSesid: string, nCaseid: string, nPresentid: string | null = null): Promise<void> {
    if (!nSesid || !nCaseid) return;

    const zeroBundleId = '00000000-0000-0000-0000-000000000000';
    const url = CommonfunctionService.buildIndividualDocUrl([
      [[zeroBundleId, 1, [], null, null, null, null, null, null, nSesid]],
      nCaseid,
      nPresentid,
      null,
    ]);

    try {
      // Ask any existing individual-doc window for this case to reply.
      await this.openTab(zeroBundleId, nCaseid, nPresentid, false);
      // Existing window is alive — ask it to add this session as a new tab.
      this.broadCastService.portMessage({
        event: BROADCAST_EVENTS.INDIVIDUAL_MULTIPLE_TAB,
        data: { nCaseid, nSesid, nPresentid, cIsindex: false },
      });
      this.openedWindow = globalThis.open('', `doc_${nCaseid}`);
      this.openedWindow?.focus();
    } catch {
      // No existing window — open a fresh named window with this session as the first tab.
      this.openedWindow = globalThis.open(url, `doc_${nCaseid}`);
      this.openedWindow?.focus();
    }
  }

  async openFactSheetMarkNav(...args: [
    nBundledetailid: any,
    nCaseid: any,
    nPresentid?: string,
    jFilter?: advanceFiler,
    cIsindex?: boolean,
    nPageno?: number,
    nFSid?: string | null,
    nRFSid?: string | null,
    nDocid?: string | null,
    nWebid?: string | null,
    nSesid?: string | null
  ]) {
    const [nBundledetailid, nCaseid, nPresentid, jFilter, cIsindex, nPageno, nFSid, nRFSid, nDocid, nWebid, nSesid] = args;
    const url = CommonfunctionService.buildIndividualDocUrl([[[nBundledetailid, nPageno || 1, [nFSid], nRFSid, nDocid, nWebid, jFilter, null, null, nSesid]], nCaseid, nPresentid, null]);
    const isFactSheet = nBundledetailid === '00000000-0000-0000-0000-000000000000';
    const eventName = isFactSheet ? BROADCAST_EVENTS.INDIVIDUAL_FACT_SHEET_OPEN : BROADCAST_EVENTS.INDIVIDUAL_MULTIPLE_TAB;

    try {
      await this.openTab(nBundledetailid, nCaseid, nPresentid, cIsindex);
      this.broadCastService.portMessage({ event: eventName, data: { nCaseid: nCaseid, bId: nBundledetailid, nPresentid, cIsindex, nPageno, nFSid, nRFSid, nDocid, nWebid, nSesid } });
      this.openedWindow = globalThis.open('', `doc_${nCaseid}`);
      this.openedWindow?.focus();
    } catch {
      this.openedWindow = globalThis.open(url, cIsindex ? `doc_${nCaseid}_index` : `doc_${nCaseid}`);
      this.openedWindow?.focus();
    }
  }
}